// Verify authentication response
pm.test("Authentication status is 200", function () {
    pm.response.to.have.status(200);
});

// Extract response data
const response = pm.response.json();

// Verify token exists
pm.test("Authentication token is generated", function () {
    pm.expect(response.token).to.be.a("string");
    pm.expect(response.token).to.not.be.empty;
});

// Save token automatically
if (response.token) {
    pm.collectionVariables.set("token", response.token);
}

// JSON Schema validation
const authSchema = {
    type: "object",
    required: ["token"],
    properties: {
        token: { type: "string" }
    },
    additionalProperties: false
};
pm.test("Response matches JSON schema", function () {
    pm.expect(tv4.validate(pm.response.json(), authSchema)).to.be.true;
});

// Verify booking creation
pm.test("Booking created successfully", function () {
    pm.response.to.have.status(200);
});

// Extract response
const response = pm.response.json();

// Verify booking ID
pm.test("Booking ID is generated", function () {
    pm.expect(response.bookingid).to.be.a("number");
});

// Verify booking details
pm.test("Booking details are correct", function () {
    pm.expect(response.booking.firstname).to.eql("John");
    pm.expect(response.booking.lastname).to.eql("Doe");
    pm.expect(response.booking.totalprice).to.eql(1500);
});

// Save booking ID automatically
if (response.bookingid) {
    pm.collectionVariables.set(
        "bookingId",
        response.bookingid
    );
}

// JSON Schema validation
const createSchema = {
    type: "object",
    required: ["bookingid", "booking"],
    properties: {
        bookingid: { type: "integer" },
        booking: {
            type: "object",
            required: ["firstname", "lastname", "totalprice", "depositpaid", "bookingdates"],
            properties: {
                firstname: { type: "string" },
                lastname: { type: "string" },
                totalprice: { type: "integer" },
                depositpaid: { type: "boolean" },
                bookingdates: {
                    type: "object",
                    required: ["checkin", "checkout"],
                    properties: {
                        checkin: { type: "string" },
                        checkout: { type: "string" }
                    }
                },
                additionalneeds: { type: "string" }
            }
        }
    }
};
pm.test("Response matches JSON schema", function () {
    pm.expect(tv4.validate(pm.response.json(), createSchema)).to.be.true;
});

